        url = next(h["url"] for h in hits if "kva.se" in h["url"])
    else:
        pdfs = [h["url"] for h in hits if h["url"].endswith(".pdf")]
        url = pdfs[0] if pdfs else hits[0]["url"]
    selected_urls.append(url)
pages = fetch_many(selected_urls, focus="All laureates, citizenship or nationality, affiliation at award, and exact prize motivation.")
