import jsonschema

proposal = {
    "summary": "Retain the discovery and reconciliation memories. Strengthen the existing source-validation memory with actionable failure diagnostics, and add a skill for recovering usable evidence from partially failed fetch batches. All supplied signal occurrences were reviewed; deterministic success does not erase recovered process failures.",
    "edits": [
        {
            "action": "update",
            "kind": "memory",
            "id": "6bc3c4962d6e4eafab63ed0189268ec3",
            "title": "Validate exact source spans before accepting extracted cells",
            "content": "PDF extraction can interleave columns and preserve long whitespace runs that model-generated quotations omit. Before inserting extracted cells into accumulated rows, require nonempty values, evidence and source lists, and verify each quote occurs exactly in every cited fetched source. Stage updates until validation completes; keep failed cells pending. Report failures with the entity, field, source URL and failed condition rather than a bare assertion, so one mismatching citation can be diagnosed without repeating extraction. Repair by locating and slicing the original source text, preserving intervening text and whitespace, or use another fetched source. Remove a mismatching citation only when the remaining citation independently supports the complete value. Recheck membership and semantic support after repair; substring membership alone does not establish semantic support. A proposed repair is not a verified repair.",
            "module": None
        },
        {
            "action": "create",
            "kind": "skill",
            "id": None,
            "title": "Recover evidence from partially failed fetch batches",
            "content": "When a fetch batch mixes usable text with failures, retain successful downloads by URL and track failures separately; exclude failure sentinels from extraction evidence. Inventory unresolved entity-field pairs after extracting and validating the usable evidence. For each remaining gap, inspect cached text first, then search for and fetch a relevant alternative source. Search snippets are leads, not substitutes for fetched proof. Do not repeat the entire successful portion of a batch or treat retrieval failure as evidence that a fact is absent. Validate the replacement quote against its fetched source and confirm that it supports the complete requested value before closing the gap. A failed URL need not eventually succeed when another verified source resolves the claim.",
            "module": None
        }
    ],
    "additional_candidates": [
        {
            "id": "additional:duplicate_reconciliation",
            "description": "Duplicate extraction records silently overwrote complementary facts before later reconciliation.",
            "evidence_refs": ["/trajectory/67", "/trajectory/71", "/trajectory/72", "/trajectory/79", "/trajectory/92", "/trajectory/99", "/entries/2"]
        },
        {
            "id": "additional:semantic_audit",
            "description": "Semantic review caught unsupported category and country-association evidence after mechanical validation passed; review findings also required adjudication against the requested field.",
            "evidence_refs": ["/trajectory/105", "/trajectory/118", "/trajectory/120", "/trajectory/121", "/trajectory/122", "/entries/1", "/entries/2"]
        },
        {
            "id": "additional:release_validation",
            "description": "Final assembled-output checks verified schema, uniqueness, coverage and exact quotations before readiness.",
            "evidence_refs": ["/trajectory/292", "/self_check/citations", "/self_check/constraint_coverage"]
        },
        {
            "id": "additional:evidence_selection_efficiency",
            "description": "Large full-page extraction inputs and blanket source exclusions were followed by successful use of a focused original PDF excerpt.",
            "evidence_refs": ["/trajectory/61", "/trajectory/72", "/trajectory/90", "/trajectory/99"]
        }
    ],
    "decisions": [
        {
            "candidate_id": "self_check:signals:stalled_search",
            "decision": "declined",
            "reason": "Reviewed all 29 occurrences: signals 0–7 are initial searches whose inspected hits did not yield named entities, signal 8 records already-known entities, and signals 9–28 concern verification or gap-filling searches for known entities. All returned hits; zero new entities does not establish lack of useful evidence. Later code sometimes hard-coded empty discovery lists, but the existing discovery memory already requires inspection and honest empty lists. No evidence justifies inventing discoveries or duplicating that guidance. The single recorded successful outcome with these signals is not evidence of consistently harmful memory behavior.",
            "evidence_refs": ["/self_check/signals/" + str(i) for i in range(29)] + ["/self_check/searches", "/self_check/discoveries", "/trajectory/6", "/trajectory/46", "/entries/0"],
            "edit_indexes": []
        },
        {
            "candidate_id": "self_check:signals:failed_fetch",
            "decision": "accepted",
            "reason": "All 13 occurrences were reviewed: three redirect loops, six HTTP 403 responses, one HTTP 404 response, two certificate errors and one broken pipe. These retrieval failures do not by themselves establish agent fault or justify domain blacklists. The trajectory retained successful downloads, identified remaining gaps and recovered through cached text and fetched alternatives; final citations all reference successful fetches. Failed-fetch sentinels nevertheless entered extraction prompts. Existing entry triggers mention reuse and alternatives, but their operative bodies do not teach this recovery workflow. Preserve the demonstrated tactic as a skill, including separation of failure status from evidence and verification before closing a gap.",
            "evidence_refs": ["/self_check/signals/" + str(i) for i in range(29,42)] + ["/trajectory/29", "/trajectory/44", "/trajectory/72", "/trajectory/92", "/trajectory/118", "/self_check/fetches", "/self_check/citations", "/entries"],
            "edit_indexes": [1]
        },
        {
            "candidate_id": "trajectory:stderr:88:0",
            "decision": "accepted",
            "reason": "The bare AssertionError occurred when one extracted quote was attached to two sources but matched only one. The validation gate correctly prevented the batch mutation. The next iteration printed per-record membership results, and the later repair retained the matching citation and successfully validated updates. Existing exact-span guidance covers rejection and repair, so update it minimally with entity/field/URL diagnostics and the conditions for removing a mismatching citation. Recovery and final passing checks support retaining the gate, not weakening it.",
            "evidence_refs": ["/trajectory/88/event/code_blocks/0/result/stderr", "/trajectory/88", "/trajectory/92", "/trajectory/99", "/entries/1", "/self_check/ok"],
            "edit_indexes": [0]
        },
        {
            "candidate_id": "additional:duplicate_reconciliation",
            "decision": "declined",
            "reason": "The extraction batches contained repeated entities; sequential assignment retained the last value, and later diagnostics confirmed two duplicated entities. Reconciliation then enforced one validated record per requested entity before mutation. Entry 2 already describes this exact failure mode and remedy, including complementary facts and regional identity. Its recorded outcome is successful and provides no basis for deletion or another edit.",
            "evidence_refs": ["/trajectory/67", "/trajectory/71", "/trajectory/72", "/trajectory/79", "/trajectory/92", "/trajectory/99", "/entries/2"],
            "edit_indexes": []
        },
        {
            "candidate_id": "additional:semantic_audit",
            "decision": "declined",
            "reason": "The audit found category-based and unlabeled country-association claims despite zero structural errors; repairs used explicit prose or labeled fields. A separate affiliation concern was adjudicated against the announcement's credited affiliation rather than accepted automatically. Existing entries already require complete semantic support and distinguish citizenship from ancestry or regional identity. Historical labels and the permissive follow-up review leave temporal interpretation uncertain, but this is not proof of a wrong answer. A separate neutral-audit/temporal-scope lesson is lower priority than the concrete diagnostic and fetch-recovery edits under the two-edit ceiling.",
            "evidence_refs": ["/trajectory/105", "/trajectory/118", "/trajectory/120", "/trajectory/121", "/trajectory/122", "/entries/1", "/entries/2"],
            "edit_indexes": []
        },
        {
            "candidate_id": "additional:release_validation",
            "decision": "declined",
            "reason": "The final execution completed schema, key uniqueness, group coverage and all-source quotation checks before readiness. The self-check reports all 308 citation records fetched and verbatim and all 168 constraint locations checked. Constraint verdicts were supplied by the agent, so this is mechanical completion rather than independent semantic proof. A broader release-gate skill would overlap existing validation coverage; prioritize the two concrete improvements instead.",
            "evidence_refs": ["/trajectory/292", "/self_check/citations", "/self_check/constraint_coverage"],
            "edit_indexes": []
        },
        {
            "candidate_id": "additional:evidence_selection_efficiency",
            "decision": "declined",
            "reason": "Full-page batches contained boilerplate and failure markers, and a blanket PDF/domain filter preceded later successful use of an explicit field in a long CV. The focused original-text slice preserved provenance and whitespace. There is no demonstrated context exhaustion, and the rationale for the early filter is not fully established. Failure-marker handling is included in the accepted recovery skill; a separate excerpt-selection or source-ranking skill is lower priority within the edit ceiling.",
            "evidence_refs": ["/trajectory/61", "/trajectory/72", "/trajectory/90", "/trajectory/99"],
            "edit_indexes": []
        }
    ]
}

jsonschema.validate(proposal, proposal_schema)
expected_ids = [c["id"] for c in context["candidate_inventory"]] + [c["id"] for c in proposal["additional_candidates"]]
assert len(expected_ids) == len(set(expected_ids))
assert sorted(d["candidate_id"] for d in proposal["decisions"]) == sorted(expected_ids)
candidates = {c["id"]: c for c in context["candidate_inventory"] + proposal["additional_candidates"]}
for d in proposal["decisions"]:
    assert any(r == e or r.startswith(e + "/") for r in d["evidence_refs"] for e in candidates[d["candidate_id"]]["evidence_refs"])
    assert bool(d["edit_indexes"]) == (d["decision"] == "accepted")
    assert all(0 <= i < len(proposal["edits"]) for i in d["edit_indexes"])
assert set(range(len(proposal["edits"]))) == {i for d in proposal["decisions"] for i in d["edit_indexes"]}
answer["content"] = json.dumps(proposal, ensure_ascii=False)
answer["ready"] = True

